.dpm-dialog .btn.primary.danger-fill { background: #c62828; border-color: #c62828; color: #ffffff; }
@media (max-width: 720px) { .dpm-dialog .ls-cols { grid-template-columns: 1fr; } }
.dpm-dialog .ar-empty { margin: 0; padding: 16px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 10px; text-align: center; font-size: 13px; color: var(--dsw-alias-label-secondary); }
