.dpm-dock { box-sizing: border-box; width: calc(100% - var(--dsh-composer-side-clearance, 0px) * 2); max-width: var(--dsh-composer-card-max-width, 100%); margin: 0 auto 8px; border: 1px solid var(--pm-brand-line); border-radius: 12px; background: var(--pm-brand-soft); color: var(--dsw-alias-label-primary); animation: fadein 240ms var(--ease); }
.dpm-dock .dock-h { display: flex; align-items: center; gap: 8px; width: 100%; min-height: 36px; padding: 0 12px; border: 0; background: transparent; color: var(--pm-brand); font: inherit; font-size: 13px; font-weight: 650; text-align: left; cursor: pointer; }
