/* ── v0.7：卡片会话标志（有活跃 = 绿，全归档 = 灰；不闪动）── */
:is(.dpm, .dpm-dialog) .foot:empty { display: none; }
:is(.dpm, .dpm-dialog) .chip.ok { background: var(--pm-ok-soft); color: var(--pm-ok); }
.dpm .chip.sess { gap: 5px; }
.dpm .chip.sess .bub { position: relative; display: grid; }
.dpm .chip.sess .bub i { position: absolute; right: -2px; top: -2px; width: 6px; height: 6px; border-radius: 999px; box-shadow: 0 0 0 1.5px var(--pm-card); }
.dpm .chip.sess.on { background: var(--pm-ok-soft); color: var(--pm-ok); border-color: color-mix(in srgb, var(--pm-ok) 28%, transparent); }
.dpm .chip.sess.on .bub i { background: var(--pm-ok); }
.dpm .chip.sess.off { background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); border-color: var(--dsw-alias-border-l2); }
.dpm .chip.sess.off .bub i { background: var(--dsw-alias-label-secondary); opacity: .55; }
/* ── v0.7：相关说明 ── */
.dpm .note-in { display: block; width: 100%; min-height: 128px; max-height: 50vh; padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); font-size: 14px; line-height: 1.6; resize: vertical; outline: 0; field-sizing: content; }
.dpm .note-in:focus { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); background: var(--dsw-alias-bg-layer-1); }
.dpm .note-bar { display: flex; align-items: center; gap: 8px; margin-top: 8px; }
.dpm .note-bar .meta { font-variant-numeric: tabular-nums; }
.dpm .note-view { padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); font-size: 14px; line-height: 1.6; white-space: pre-wrap; word-break: break-word; }
.dpm .note-view a { color: var(--pm-brand); text-decoration: underline; text-underline-offset: 2px; word-break: break-all; }
.dpm .note-view a:hover { text-decoration-thickness: 2px; }
/* ── 0.10：相关说明超长折叠（不再内部滚动）── */
.dpm .note-wrap.clamp .note-view { max-height: 172px; overflow: hidden; -webkit-mask-image: linear-gradient(#000 calc(100% - 44px), transparent); mask-image: linear-gradient(#000 calc(100% - 44px), transparent); }
.dpm .note-more { margin-top: 4px; color: var(--pm-brand); }
.dpm .note-more[hidden] { display: none; }
.dpm .note-more svg.i { transition: transform 160ms var(--ease); }
.dpm .note-more[aria-expanded="true"] svg.i { transform: rotate(180deg); }
/* ── 0.10：相关链接 ── */
.dpm .wl-list { display: flex; flex-direction: column; gap: 6px; }
.dpm .wl { position: relative; display: flex; align-items: center; gap: 4px; min-height: 40px; padding: 4px 4px 4px 2px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-layer-1); }
.dpm .wl:hover { border-color: var(--dsw-alias-border-l3); }
.dpm .wl .wgrip { flex: none; width: 22px; height: 28px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 6px; background: none; color: var(--dsw-alias-label-secondary); opacity: .45; cursor: grab; touch-action: none; }
.dpm .wl .wgrip svg.i { width: 14px; height: 14px; }
.dpm .wl:hover .wgrip, .dpm .wl .wgrip:focus-visible { opacity: 1; }
.dpm .wl .wl-a { flex: 1; min-width: 0; display: flex; align-items: center; gap: 8px; padding: 4px 2px; color: var(--dsw-alias-label-primary); text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 6px; }
.dpm .wl .wl-a.ro { padding-left: 8px; }
.dpm .wl .wl-a svg.i { flex: none; color: var(--dsw-alias-label-secondary); }
.dpm .wl .wl-a .t { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm .wl .wl-a:hover .t { color: var(--pm-brand); text-decoration: underline; text-underline-offset: 2px; }
.dpm .wl .chip { flex: none; height: 20px; }
/* 0.20：编辑 / 删除常驻显示（拖动把手仍是悬停出现） */
.dpm .wl .acts { display: flex; gap: 2px; flex: none; }
@media (hover: none) { .dpm .wl .acts, .dpm .wl .wgrip { opacity: 1; } }
.dpm .wl .ib.sm { width: 28px; height: 28px; }
.dpm .wl .ib.del:hover { color: #c62828; background: rgba(198, 40, 40, .08); }
