.dpm-sic .pill { display: inline-flex; align-items: center; gap: 5px; flex: none; height: 24px; padding: 0 8px; border-radius: 999px; background: var(--pm-on-chip); font-size: 12px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
