.dpm-sic .ma-s + .ma-s { margin-top: 8px; padding-top: 8px; border-top: 1px dashed var(--dsw-alias-border-l2); }
.dpm-sic .ma-t { display: flex; align-items: center; gap: 6px; margin: 0 0 4px; padding-left: 2px; font-size: 12px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.dpm-sic .ma-t svg.i { width: 13px; height: 13px; }
.dpm-sic .ma-t .c { font-weight: 500; font-variant-numeric: tabular-nums; }
.dpm-sic .row { display: flex; align-items: center; gap: 8px; min-height: 30px; padding: 3px 4px 3px 6px; border-radius: 8px; font-size: 13px; transition: background 140ms var(--ease); }
.dpm-sic .row:hover { background: var(--dsw-alias-bg-layer-1); }
.dpm-sic .row.gone .v { text-decoration: line-through; }
.dpm-sic .row .k { flex: none; width: 108px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic .row .v { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--dsw-alias-label-secondary); }
.dpm-sic .row .v.pri { color: var(--dsw-alias-label-primary); }
.dpm-sic .row .ty { flex: none; font-size: 11px; color: var(--dsw-alias-label-secondary); padding: 0 6px; height: 18px; line-height: 18px; border-radius: 5px; background: var(--dsw-alias-bg-module-platform); }
.dpm-sic .row .ib { width: 26px; height: 26px; opacity: 0; }
.dpm-sic .row:hover .ib, .dpm-sic .row .ib:focus-visible, .dpm-sic .row .ib.copied { opacity: 1; }
.dpm-sic .task .bx { width: 14px; height: 14px; flex: none; border: 1.5px solid var(--dsw-alias-border-l3); border-radius: 4px; display: grid; place-items: center; }
.dpm-sic .task .bx svg.i { width: 10px; height: 10px; stroke-width: 3; }
.dpm-sic .task.dn .bx { background: var(--pm-ok); border-color: var(--pm-ok); color: #fff; }
.dpm-sic .task.dn .v { text-decoration: line-through; }
.dpm-sic .note { margin: 0 2px; padding: 6px 8px; border-radius: 8px; background: var(--dsw-alias-bg-layer-1); font-size: 12.5px; line-height: 1.6; color: var(--dsw-alias-label-secondary); white-space: pre-wrap; max-height: 160px; overflow: auto; }
.dpm-sic .empty { margin: 0; padding: 2px 6px; font-size: 12px; color: var(--dsw-alias-label-secondary); }

/* 复制按钮（与 dsh-manage-sessions 一致：图标 → 对勾，1.2s 复原） */
:is(.dpm-sic, .dpm) .cp svg { width: 15px; height: 15px; transition: opacity .16s ease, transform .16s ease; }
:is(.dpm-sic, .dpm) .cp .cp-ck { position: absolute; inset: 0; margin: auto; opacity: 0; transform: scale(.55); color: var(--pm-ok); }
:is(.dpm-sic, .dpm) .cp.copied .cp-ico { opacity: 0; transform: scale(.55); }
:is(.dpm-sic, .dpm) .cp.copied .cp-ck { opacity: 1; transform: scale(1); }
.dpm .wl .cp { position: relative; }

/* 悬停走马灯：只在文字被截断且鼠标悬停时跑 */
.mq-on { text-overflow: clip !important; }
.mq-track { display: inline-block; white-space: nowrap; animation: dpmmq var(--mq-dur, 8s) linear infinite; }
.mq-track > span { padding-right: 40px; }
@keyframes dpmmq { from { transform: translateX(0); } to { transform: translateX(-50%); } }

/* 看板直达：卡片闪一下蓝框 */
.dpm .card.dpm-flash { animation: dpmflash 1.2s var(--ease); }
@keyframes dpmflash { 0%, 35% { box-shadow: 0 0 0 4px var(--pm-brand-soft), 0 0 0 1px var(--pm-brand); } }

/* 「AI 收到的原文」浮层 */
.dpm-ov { position: fixed; inset: 0; z-index: 1500; display: grid; place-items: center; padding: 24px; background: rgba(15, 17, 21, .32); animation: dpmfade 160ms ease; color: var(--dsw-alias-label-primary); font-size: 14px; line-height: 1.5;
  --pm-brand: #2f5fcc; --pm-lane: #f7f8fa; --pm-shadow-2: 0 8px 28px rgba(15, 17, 21, .12); --ease: cubic-bezier(.2, .8, .2, 1); }
body[data-ds-dark-theme] .dpm-ov { background: rgba(0, 0, 0, .55); --pm-brand: #6c97ff; --pm-lane: #1c1c1e; --pm-shadow-2: 0 12px 32px rgba(0, 0, 0, .5); }
.dpm-ov * { box-sizing: border-box; }
.dpm-ov.out { opacity: 0; transition: opacity 160ms ease; }
@keyframes dpmfade { from { opacity: 0; } }
.dpm-ov button { font: inherit; color: inherit; cursor: pointer; }
.dpm-ov :focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; border-radius: 8px; }
.dpm-ov svg.i { width: 16px; height: 16px; flex: none; stroke: currentColor; fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-ov .dlg { width: min(780px, 100%); max-height: min(84vh, 760px); display: flex; flex-direction: column; border: 1px solid var(--dsw-alias-border-l2); border-radius: 16px; background: var(--dsw-alias-bg-layer-1, #fff); box-shadow: var(--pm-shadow-2); animation: dpmpop 220ms var(--ease); }
.dpm-ov .dlg-h { display: flex; align-items: flex-start; gap: 10px; padding: 16px 12px 10px 20px; }
.dpm-ov .dlg-h h2 { margin: 0; font-size: 15px; }
.dpm-ov .dlg-h p { margin: 2px 0 0; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-ov .ib { width: 30px; height: 30px; display: grid; place-items: center; border: 0; border-radius: 8px; background: transparent; color: var(--dsw-alias-label-secondary); }
.dpm-ov .ib:hover { background: var(--pm-lane); color: var(--dsw-alias-label-primary); }
.dpm-ov .tabs { display: flex; gap: 16px; padding: 0 20px; border-bottom: 1px solid var(--dsw-alias-border-l2); }
.dpm-ov .tabs button { height: 40px; margin-bottom: -1px; padding: 0 2px; border: 0; border-bottom: 2px solid transparent; background: transparent; font-size: 13px; color: var(--dsw-alias-label-secondary); }
.dpm-ov .tabs button[aria-selected="true"] { color: var(--dsw-alias-label-primary); font-weight: 650; border-bottom-color: var(--pm-brand); }
.dpm-ov .tabs .c { margin-left: 6px; font-size: 11.5px; font-weight: 400; color: var(--dsw-alias-label-secondary); }
.dpm-ov .dlg-b { flex: 1; min-height: 0; overflow: auto; padding: 12px 20px 16px; }
.dpm-ov .hint { margin: 0 0 10px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-ov .raw { margin: 0; padding: 12px 14px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--pm-lane); font: 12px/1.7 ui-monospace, SFMono-Regular, Menlo, monospace; color: var(--dsw-alias-label-primary); white-space: pre-wrap; word-break: break-word; }
.dpm-ov .inj { border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; }
.dpm-ov .inj + .inj { margin-top: 8px; }
.dpm-ov .inj summary { display: flex; align-items: center; gap: 8px; min-height: 42px; padding: 0 12px; cursor: pointer; list-style: none; font-size: 13px; border-radius: 10px; }
.dpm-ov .inj summary::-webkit-details-marker { display: none; }
.dpm-ov .inj summary:hover { background: var(--pm-lane); }
.dpm-ov .inj summary b { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }
.dpm-ov .inj summary .sp { flex: 1; }
.dpm-ov .inj summary .m { flex: none; font-size: 12px; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
.dpm-ov .inj summary .tag { flex: none; height: 18px; padding: 0 6px; border-radius: 5px; border: 1px solid var(--dsw-alias-border-l2); font-size: 11px; line-height: 16px; color: var(--dsw-alias-label-secondary); }
.dpm-ov .inj summary svg.i { transform: rotate(-90deg); transition: transform 200ms var(--ease); }
.dpm-ov .inj[open] summary svg.i { transform: none; }
.dpm-ov .inj .raw { margin: 0 10px 10px; max-height: 50vh; overflow: auto; }
.dpm-ov .dlg-f { display: flex; align-items: center; gap: 8px; padding: 10px 16px 14px 20px; border-top: 1px solid var(--dsw-alias-border-l2); }
.dpm-ov .dlg-f .meta { flex: 1; font-size: 12px; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
.dpm-ov .btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 30px; padding: 0 10px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 9px; background: var(--dsw-alias-bg-layer-1); font-size: 13px; }
.dpm-ov .btn:hover { background: var(--pm-lane); }
@media (prefers-reduced-motion: reduce) { .dpm-sic *, .dpm-sic, .dpm-ov, .dpm-ov * { animation-duration: 1ms !important; animation-iteration-count: 1 !important; transition-duration: 1ms !important; } .mq-track { animation: none !important; } }
.dpm-sic .plan li { display: list-item; font-size: 12px; line-height: 1.7; }
.dpm-sic .plan li b { flex: initial; }
/* 宿主的输入区是 flex 列：卡片不许被压扁（收起实测被压到 13px） */
.dpm-sic { flex: none; min-height: 40px; }
.dpm-sic .scroll { max-height: min(46vh, 440px); }

/* ══ 0.20 会话信息卡：落盘这一轮的结局 / 同名检测 / 卡片组落盘文件夹 / 迁移 ══ */
.dpm-sic .pill.bad { color: var(--pm-bad); background: color-mix(in srgb, var(--pm-bad) 8%, var(--dsw-alias-bg-layer-1)); }
.dpm-sic .lf.stopped { border-color: color-mix(in srgb, var(--pm-bad) 40%, transparent); }
.dpm-sic .lf .l2.bad { color: var(--pm-bad); }
.dpm-sic .lf .st.stop, .dpm-sic .lf .st.stop svg.i { color: var(--pm-bad); }
.dpm-sic .lf .st.wait, .dpm-sic .lf .st.wait svg.i { color: var(--pm-brand); }
.dpm-sic .tag.legacy { border-color: color-mix(in srgb, var(--pm-bad) 40%, transparent); color: var(--pm-bad); }
.dpm-sic .hint-l { display: flex; align-items: center; gap: 6px; min-height: 28px; margin: 0 8px 6px; padding: 0 8px; border-radius: 8px; background: var(--pm-on-grp); font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-sic .hint-l .em { flex: none; color: var(--pm-bad); font-weight: 600; }
.dpm-sic .hint-l .mq { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic .mk.dup { border-color: var(--pm-brand); }
.dpm-sic .mk .tok span.dup { border-color: var(--pm-brand); background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm-sic .mk input:disabled { opacity: .6; }
.dpm-sic .mt { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 260ms var(--ease); }
.dpm-sic .mt.on { grid-template-rows: 1fr; }
.dpm-sic .mt > .in { min-height: 0; overflow: hidden; }
.dpm-sic .mt-b { margin: 0 8px 8px; padding: 8px; border-radius: 10px; background: var(--pm-on-grp); }
.dpm-sic .mt-t { display: flex; align-items: center; gap: 6px; margin: 0 0 6px; padding: 0 2px; font-size: 12px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.dpm-sic .mt-t .why { font-weight: 400; }
.dpm-sic .cand { display: flex; align-items: center; gap: 10px; padding: 8px 8px 8px 10px; border-radius: 10px; border: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-layer-1); }
.dpm-sic .cand + .cand { margin-top: 6px; }
.dpm-sic .cand.exact { border-color: var(--pm-brand); box-shadow: 0 0 0 1px var(--pm-brand); }
.dpm-sic .cand .txt { flex: 1; min-width: 0; }
.dpm-sic .cand .l1 { display: flex; align-items: center; gap: 6px; min-width: 0; }
.dpm-sic .cand .nm { font-weight: 650; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic .cand .nm mark { background: color-mix(in srgb, var(--pm-brand) 18%, transparent); color: inherit; border-radius: 3px; }
.dpm-sic .cand .pj { flex: none; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-sic .cand .tag { max-width: 40%; overflow: hidden; text-overflow: ellipsis; }
.dpm-sic .cand .l2 { margin-top: 2px; font-size: 12px; color: var(--dsw-alias-label-secondary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic .cand .l3 { margin-top: 3px; font-size: 11.5px; color: var(--dsw-alias-label-secondary); }
.dpm-sic .cand .l3 b { font-weight: 600; color: var(--dsw-alias-label-primary); }
.dpm-sic .cacts { display: flex; gap: 6px; flex: none; }
.dpm-sic .mt-f { margin: 6px 2px 0; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-sic .mt-f .lnk { text-decoration: underline; text-underline-offset: 2px; }
.dpm-sic .fo { margin: 0 8px 8px; padding: 10px; border-radius: 10px; border: 1px solid var(--pm-brand-line); background: var(--dsw-alias-bg-layer-1); animation: dpmpop 220ms var(--ease); }
.dpm-sic .fo-t { margin: 0; font-size: 13px; font-weight: 650; }
.dpm-sic .fo-s { margin: 2px 0 8px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-sic .fo-r { display: flex; align-items: center; gap: 6px; }
.dpm-sic .fo-r .fld { flex: 1; min-width: 0; display: flex; align-items: center; gap: 2px; height: 30px; padding: 0 8px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 8px; font: 12.5px ui-monospace, SFMono-Regular, Menlo, monospace; }
.dpm-sic .fo-r .fld:focus-within { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm-sic .fo-r .pre { color: var(--dsw-alias-label-secondary); }
.dpm-sic .fo-r input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; font: inherit; }
.dpm-sic .fo-e { margin: 4px 0 0; font-size: 12px; color: var(--pm-bad); }
.dpm-sic .fo-e:empty { display: none; }

/* ══ 0.20 卡片组标题旁统计：卡片数醒目（0 张变灰）+ 活跃会话实时 ══ */
/* 统计一行不折：窄的时候先省略灰色小字、再省略统计，组名最后才截断 */
.dpm .gstat { display: inline-flex; align-items: center; gap: 6px; min-width: 0; flex-wrap: nowrap; overflow: hidden; }
.dpm .gstat .cnt { flex: none; }
/* 卡片数与活跃会话胶囊不压缩；泳道窄（详情打开时）先藏仓库 / 阶段小字，再截断组名 */
.dpm .lane-h { container-type: inline-size; }
@media (min-width: 721px) { .dpm .lane-hit .gstat { flex: none; } .dpm .lane-hit h2 { flex: 0 1 auto; min-width: 4em; } }
@container (max-width: 1000px) { .dpm .gstat .quiet { display: none; } }
@container (max-width: 820px) { .dpm .lane-hit .lb { display: none; } }
.dpm .gstat .cnt { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 9px; border-radius: 999px; font-size: 12px; white-space: nowrap; font-variant-numeric: tabular-nums; transition: background 200ms var(--ease), color 200ms var(--ease); }
.dpm .gstat .cnt b { font-size: 13px; font-weight: 700; }
.dpm .gstat .cnt.cards { background: var(--pm-brand); color: var(--pm-brand-ink, #fff); }
.dpm .gstat .cnt.cards.zero { background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); opacity: .75; }
.dpm .gstat .cnt.live { background: var(--dsw-alias-bg-layer-1); color: var(--pm-ok, #1f7a4d); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pm-ok, #1f7a4d) 35%, transparent); }
.dpm .gstat .cnt.live i { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
.dpm .gstat .cnt.live.zero { color: var(--dsw-alias-label-secondary); box-shadow: inset 0 0 0 1px var(--dsw-alias-border-l2); opacity: .75; }
.dpm .gstat .cnt.live.zero i { background: transparent; border: 1.5px solid currentColor; box-sizing: border-box; }
.dpm .gstat .cnt.bump { animation: dpm-cnt-bump 420ms cubic-bezier(.2, .8, .2, 1); }
.dpm .gstat .quiet { min-width: 0; overflow: hidden; text-overflow: ellipsis; font-size: 12px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
@keyframes dpm-cnt-bump { 40% { transform: scale(1.14); } }
/* 0.20 新建会话忙态 */
:is(.dpm, .dpm-dialog) .btn .spin { width: 13px; height: 13px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: dpmrot .7s linear infinite; }
:is(.dpm, .dpm-dialog) .btn[aria-busy="true"] { opacity: .75; cursor: progress; }
/* 0.20 卡片组设置：落盘文件夹 */
.dpm-dialog .lf-fld { display: flex; align-items: center; gap: 2px; height: 36px; padding: 0 10px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 10px; font: 13px ui-monospace, SFMono-Regular, Menlo, monospace; background: var(--dsw-alias-bg-layer-1); }
.dpm-dialog .lf-fld:focus-within { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm-dialog .lf-fld .pre { color: var(--dsw-alias-label-secondary); }
.dpm-dialog .lf-fld input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; font: inherit; color: inherit; }

/* 0.20 侧栏：当前打开的空会话由插件画（选中底色同宿主），新建中的占位行 */
.dpm-blank.cur { background: var(--dsw-alias-interactive-bg-selected, rgba(15, 17, 21, .08)); color: var(--dsw-alias-label-primary, #0f1115); font-weight: 600; }
.dpm-blank.pend { cursor: progress; opacity: .8; }
.dpm-blank.pend .dpm-blank-s { position: relative; }
.dpm-blank.pend .dpm-blank-s::after { content: ""; position: absolute; left: 3px; top: 5px; width: 10px; height: 10px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: dpmrot .7s linear infinite; box-sizing: border-box; }

entries.ru:
.dpm, .dpm-pop, .dpm-dock, .dpm-dialog, .dpm-toasts {
  --pm-select: rgba(15, 17, 21, .06);
  --pm-brand: #2f5fcc; --pm-brand-ink: #ffffff; --pm-brand-soft: #eaf0fd; --pm-brand-soft-2: #d9e4fb; --pm-brand-line: #c3d3f7;
  --pm-ok: #146c3f; --pm-ok-soft: #e6faed; --pm-warn: #94480a; --pm-warn-soft: #fff3e2; --pm-warn-line: #f2c38c;
  --pm-card: var(--dsw-alias-bg-layer-1, #ffffff); --pm-lane: #f7f8fa;
  --pm-shadow: 0 1px 2px rgba(15, 17, 21, .06); --pm-shadow-2: 0 8px 28px rgba(15, 17, 21, .12);
  --ease: cubic-bezier(.2, .8, .2, 1);
}
body[data-ds-dark-theme] :is(.dpm, .dpm-pop, .dpm-dock, .dpm-dialog, .dpm-toasts) {
  --pm-select: rgba(255, 255, 255, .08);
  --pm-brand: #6c97ff; --pm-brand-ink: #0b1020; --pm-brand-soft: #1d2a4a; --pm-brand-soft-2: #26365e; --pm-brand-line: #35508f;
  --pm-ok: #56cc86; --pm-ok-soft: #1f3a29; --pm-warn: #f2a650; --pm-warn-soft: #33240f; --pm-warn-line: #6b4a1f;
  --pm-card: var(--dsw-alias-bg-layer-1, #232324); --pm-lane: #1c1c1e;
  --pm-shadow: 0 1px 2px rgba(0, 0, 0, .4); --pm-shadow-2: 0 12px 32px rgba(0, 0, 0, .5);
}
.dpm { position: relative; display: flex; flex-direction: column; height: 100%; min-height: 0; min-width: 0; font-size: 14px; line-height: 1.5; color: var(--dsw-alias-label-primary); background: var(--dsw-alias-bg-base); }
.dpm-pop, .dpm-dock, .dpm *, .dpm-pop *, .dpm-dock *, .dpm-dialog * { box-sizing: border-box; }
.dpm button, .dpm input, .dpm select, .dpm textarea, .dpm-dialog button, .dpm-dialog input, .dpm-dialog select, .dpm-dialog textarea, .dpm-pop input { font: inherit; color: inherit; }
.dpm svg.i, .dpm-pop svg.i, .dpm-dock svg.i, .dpm-dialog svg.i, .dpm-toasts svg.i { width: 16px; height: 16px; flex: none; stroke: currentColor; fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm :focus-visible, .dpm-dialog :focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; border-radius: 8px; }
.dpm .sr-only, .dpm-dialog .sr-only, .dpm-pop .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.dpm .grow, .dpm-pop .grow, .dpm-dock .grow, .dpm-dialog .grow { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm .meta, .dpm-dialog .meta { font-size: 13px; color: var(--dsw-alias-label-secondary); }
.dpm .mono, .dpm-dialog .mono { font-family: "SF Mono", Menlo, monospace; font-size: 12px; color: var(--dsw-alias-label-secondary); word-break: break-all; }
.dpm-err { margin: 12px 24px 0; padding: 8px 12px; border: 1px solid var(--pm-warn-line); border-radius: 10px; background: var(--pm-warn-soft); color: var(--pm-warn); font-size: 13px; }

/* ── Плагин: оверлей выбора проекта ── */
.dpm-pop { position: fixed; z-index: 30; width: 300px; padding: 8px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 12px; background: var(--dsw-alias-bg-layer-1); box-shadow: var(--pm-shadow-2); animation: popin 180ms var(--ease); }
@keyframes popin { from { opacity: 0; transform: translateY(-4px) scale(.98); } }
/* Оверлей выбора карточки: сплошной фон (явный запасной цвет, не прозрачный даже без токена хоста); в строке два уровня информации; подсветка общая для мыши и клавиатуры */
.dpm-pop { --pm-pop-bg: var(--dsw-alias-bg-layer-1, #ffffff); --pm-pop-sub: var(--dsw-alias-bg-module-platform, #f5f6f7); width: 340px; padding: 0; overflow: hidden; background: var(--pm-pop-bg); background-color: var(--pm-pop-bg); color: var(--dsw-alias-label-primary, #0f1115); transform-origin: top left; }
body[data-ds-dark-theme] .dpm-pop { --pm-pop-bg: var(--dsw-alias-bg-layer-1, #232324); --pm-pop-sub: var(--dsw-alias-bg-module-platform, #353638); color: var(--dsw-alias-label-primary, #f9fafb); }
.dpm-pop .ph { padding: 12px 14px 8px; }
.dpm-pop h3 { margin: 0; font-size: 14px; font-weight: 650; color: var(--dsw-alias-label-primary); }
.dpm-pop .ph p { margin: 2px 0 0; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-pop .qw { position: relative; margin: 0 12px 8px; }
.dpm-pop .qw svg.i { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: var(--dsw-alias-label-secondary); pointer-events: none; }
.dpm-pop input { width: 100%; height: 36px; margin: 0; padding: 0 12px 0 32px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 8px; background: var(--pm-pop-sub); outline: 0; transition: border-color 120ms var(--ease), box-shadow 120ms var(--ease); }
.dpm-pop input:focus { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm-pop ul { max-height: 320px; overflow: auto; margin: 0; padding: 0 6px 6px; list-style: none; scroll-padding: 32px 0 4px; }
.dpm-pop .grp { position: sticky; top: 0; z-index: 1; display: flex; align-items: center; gap: 6px; padding: 8px 8px 4px; background: var(--pm-pop-bg); font-size: 12px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.dpm-pop .grp .n { margin-left: auto; font-weight: 500; }
.dpm-pop .empty { padding: 28px 12px; text-align: center; font-size: 13px; color: var(--dsw-alias-label-secondary); }
.dpm-pop .opt { position: relative; display: flex; flex-direction: column; gap: 3px; padding: 8px 30px 8px 12px; border-radius: 8px; cursor: pointer; transition: background 120ms var(--ease); }
.dpm-pop .opt .nm { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; font-weight: 500; color: var(--dsw-alias-label-primary); }
.dpm-pop .opt .nm mark { background: transparent; color: var(--pm-brand); font-weight: 700; }
.dpm-pop .opt .mt { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-pop .opt .stg { display: inline-flex; align-items: center; height: 18px; padding: 0 6px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 999px; background: var(--pm-pop-sub); color: var(--dsw-alias-label-primary); }
.dpm-pop .opt .mm { display: inline-flex; align-items: center; gap: 3px; color: var(--pm-brand); }
.dpm-pop .opt .mm.no { color: var(--pm-warn); }
.dpm-pop .opt .mm svg.i, .dpm-pop .opt .go svg.i { width: 13px; height: 13px; }
.dpm-pop .opt .go { position: absolute; right: 10px; top: 50%; display: grid; color: var(--pm-brand); opacity: 0; transform: translate(-4px, -50%); transition: opacity 120ms var(--ease), transform 120ms var(--ease); }
.dpm-pop .opt:hover { background: var(--pm-select); }
.dpm-pop .opt[aria-selected="true"] { background: var(--pm-brand-soft); }
.dpm-pop .opt[aria-selected="true"] .nm { color: var(--pm-brand); }
.dpm-pop .opt[aria-selected="true"]::before { content: ""; position: absolute; left: 3px; top: 10px; bottom: 10px; width: 3px; border-radius: 3px; background: var(--pm-brand); }
.dpm-pop .opt[aria-selected="true"] .go { opacity: 1; transform: translate(0, -50%); }
.dpm-pop .hint { display: flex; flex-wrap: wrap; gap: 4px 12px; margin: 0; padding: 8px 14px; border-top: 1px solid var(--dsw-alias-border-l2); background: var(--pm-pop-sub); font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-pop .hint span { display: inline-flex; align-items: center; gap: 4px; }
.dpm-pop kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border: 1px solid var(--dsw-alias-border-l2); border-bottom-width: 2px; border-radius: 4px; background: var(--pm-pop-bg); font: 11px/1 ui-monospace, SFMono-Regular, Menlo, monospace; color: var(--dsw-alias-label-primary); }
/* Диалог «Новая сессия» */
.dpm-dialog .ns-sug { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; padding: 8px 12px; border: 1px solid var(--pm-warn-line); border-radius: 10px; background: var(--pm-warn-soft); font-size: 13px; }
.dpm-dialog .ns-sug .grow { white-space: normal; }
.dpm-dialog .ns-sec { display: flex; align-items: center; margin: 16px 0 8px; font-size: 12px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .ns-row { display: flex; align-items: center; gap: 12px; margin-bottom: 6px; padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; cursor: pointer; transition: background 120ms var(--ease), border-color 120ms var(--ease), box-shadow 120ms var(--ease); }
.dpm-dialog .ns-row:hover { background: var(--pm-select); }
.dpm-dialog .ns-row:has(input:checked) { border-color: var(--pm-brand); background: var(--pm-brand-soft); box-shadow: inset 0 0 0 1px var(--pm-brand); }
.dpm-dialog .ns-row:has(input:focus-visible) { outline: 2px solid var(--pm-brand); outline-offset: 2px; }
.dpm-dialog .ns-row input { flex: none; width: 16px; height: 16px; margin: 0; accent-color: var(--pm-brand); }
.dpm-dialog .ns-row .txt { flex: 1; min-width: 0; }
.dpm-dialog .ns-row .nm { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; font-weight: 500; }
.dpm-dialog .ns-row .sub { display: flex; align-items: center; gap: 6px; margin-top: 2px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .ns-row .sub .chip { height: 20px; }
.dpm-dialog .ns-row .ni { flex: none; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm-dialog .ns-row:has(input:checked) .ni { background: var(--pm-brand); color: var(--pm-brand-ink); }
.dpm-dialog .ns-row.dis { cursor: default; }
.dpm-dialog .ns-row.dis:hover { background: transparent; }
.dpm-dialog .ns-row.dis .nm, .dpm-dialog .ns-row.dis .sub > span:not(.chip) { color: var(--dsw-alias-label-secondary); }
.dpm-dialog .ns-row.fresh { animation: nsfresh 700ms var(--ease); }
@keyframes nsfresh { 0% { background: var(--pm-brand-soft); } 100% { background: transparent; } }
.dpm-dialog .ns-empty { padding: 12px; border: 1px dashed var(--dsw-alias-border-l2); border-radius: 10px; font-size: 13px; color: var(--dsw-alias-label-secondary); text-align: center; }
.dpm-dialog .btn.xs { flex: none; min-height: 28px; padding: 0 8px; gap: 4px; border-radius: 8px; font-size: 13px; }
.dpm-dialog .btn.xs svg.i { width: 14px; height: 14px; }
.dpm-dock.nolink { border-color: var(--pm-warn-line); background: var(--pm-warn-soft); }
.dpm-dock.nolink .dock-h { color: var(--pm-warn); cursor: default; }
.dpm-dock.nolink .dock-h .grow { white-space: normal; }
.dpm-dock .btn.xs { display: inline-flex; align-items: center; gap: 4px; flex: none; min-height: 26px; padding: 0 8px; border: 1px solid var(--pm-warn-line); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); font: inherit; font-size: 12px; cursor: pointer; }
.dpm-dock .btn.xs:hover { background: var(--pm-select); }
.dpm-dock .btn.xs svg.i { width: 13px; height: 13px; }

/* ── Плагин: панель проектной доски ── */
@keyframes fadein { from { opacity: 0; } }
:is(.dpm, .dpm-dialog) .pm-top { display: flex; align-items: center; gap: 12px; padding: 16px 24px; border-bottom: 1px solid var(--dsw-alias-border-l2); flex-wrap: wrap; }
:is(.dpm, .dpm-dialog) .pm-top h1 { margin: 0; font-size: 20px; font-weight: 650; line-height: 1.3; }
:is(.dpm, .dpm-dialog) .pm-top p { margin: 4px 0 0; font-size: 13px; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .pm-top .ttl { flex: 1 1 260px; min-width: 0; }
:is(.dpm, .dpm-dialog) .search { display: flex; align-items: center; gap: 8px; height: 36px; width: 220px; padding: 0 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .search input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; }
:is(.dpm, .dpm-dialog) .search input::placeholder { color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 36px; padding: 0 12px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 10px; background: var(--dsw-alias-bg-layer-1); font-weight: 600; white-space: nowrap; transition: background 160ms var(--ease), transform 120ms var(--ease); }
:is(.dpm, .dpm-dialog) .btn:hover { background: var(--dsw-alias-button-floating-hover); }
:is(.dpm, .dpm-dialog) .btn:active { transform: translateY(1px); }
:is(.dpm, .dpm-dialog) .btn.primary { background: var(--pm-brand); border-color: var(--pm-brand); color: var(--pm-brand-ink); }
:is(.dpm, .dpm-dialog) .btn.primary:hover { filter: brightness(1.08); }
:is(.dpm, .dpm-dialog) .btn.ghost { border-color: transparent; background: transparent; }
:is(.dpm, .dpm-dialog) .btn.ghost:hover { background: var(--pm-select); }
:is(.dpm, .dpm-dialog) .btn.lg { width: 100%; min-height: 44px; font-size: 15px; }
:is(.dpm, .dpm-dialog) .btn:disabled { opacity: .5; cursor: not-allowed; }
:is(.dpm, .dpm-dialog) .ib { width: 32px; height: 32px; display: grid; place-items: center; border: 0; border-radius: 8px; background: transparent; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .ib:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
:is(.dpm, .dpm-dialog) .pm-body { position: relative; flex: 1; min-height: 0; min-width: 0; display: flex; }
:is(.dpm, .dpm-dialog) .board-wrap { position: relative; flex: 1; min-width: 0; overflow: auto; padding: 16px 24px 24px; }
:is(.dpm, .dpm-dialog) .lane { min-width: 0; margin-bottom: 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 12px; background: var(--pm-lane); }
:is(.dpm, .dpm-dialog) .lane-h { display: flex; align-items: center; gap: 8px; padding: 8px 12px; flex-wrap: wrap; }
:is(.dpm, .dpm-dialog) .lane-h h2 { margin: 0; font-size: 15px; font-weight: 650; line-height: 1.4; }
:is(.dpm, .dpm-dialog) .lane-h .meta { font-size: 13px; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .lane-h .sp { flex: 1; }
:is(.dpm, .dpm-dialog) .lane.collapsed .chev { transform: rotate(-90deg); }
:is(.dpm, .dpm-dialog) .lane.collapsed .lane-in { display: none; }
/* Шапка группы: клик по всей левой области раскрывает/сворачивание; справа ручка для сортировки перетаскиванием */
.dpm .lane { position: relative; }
.dpm .lane-hit { flex: 1 1 auto; min-width: 0; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; align-self: stretch; margin: -4px 0 -4px -6px; padding: 4px 8px 4px 6px; border-radius: 8px; cursor: pointer; user-select: none; transition: background 120ms var(--ease); }
.dpm .lane-hit:hover { background: var(--pm-select); }
.dpm .lane-hit h2 { display: flex; }
.dpm .lane-h .tg { display: inline-flex; align-items: center; gap: 6px; min-height: 32px; padding: 0 4px 0 0; border: 0; border-radius: 6px; background: none; color: inherit; font: inherit; font-size: 15px; font-weight: 650; text-align: left; cursor: pointer; }
.dpm .lane-h .tg .chev-b { width: 24px; height: 24px; display: grid; place-items: center; color: var(--dsw-alias-label-secondary); }
.dpm .lane-hit:hover .tg .chev-b { color: var(--dsw-alias-label-primary); }
.dpm .lane-h .chev { transition: transform 200ms var(--ease); }
.dpm .ib.grip { cursor: grab; touch-action: none; }
.dpm.gdragging, .dpm.gdragging * { cursor: grabbing !important; user-select: none; }
.dpm .lane.lifting { opacity: .5; }
.dpm .lane.gins-before::before, .dpm .lane.gins-after::after { content: ""; position: absolute; left: 0; right: 0; height: 3px; border-radius: 3px; background: var(--pm-brand); pointer-events: none; }
.dpm .lane.gins-before::before { top: -8px; }
.dpm .lane.gins-after::after { bottom: -8px; }
.dpm .lane.moved { animation: moved 360ms var(--ease); }
.dpm .lane.landed { animation: lland 700ms var(--ease); }
@keyframes lland { 0% { box-shadow: 0 0 0 2px var(--pm-brand); } 100% { box-shadow: 0 0 0 2px transparent; } }
@media (max-width: 720px), (pointer: coarse) { .dpm .lane-h .tg { min-height: 44px; } }
/* Панель деталей обновляется на месте: без повторного выезда и появления строк */
.dpm .detail.stay, .dpm .detail.stay * { animation: none !important; }
:is(.dpm, .dpm-dialog) .lane-in { position: relative; display: flex; flex-direction: column; gap: 12px; padding: 0 12px 12px; overflow-x: auto; }
:is(.dpm, .dpm-dialog) .shead, .lane-b { display: grid; grid-template-columns: repeat(var(--cols), minmax(212px, 1fr)); gap: 8px; }
:is(.dpm, .dpm-dialog) .lane-b { align-items: start; }
:is(.dpm, .dpm-dialog) .colh { display: flex; align-items: center; gap: 8px; padding: 8px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); font-size: 14px; font-weight: 650; }
:is(.dpm, .dpm-dialog) .colh .nm { white-space: nowrap; }
:is(.dpm, .dpm-dialog) .colh .n { height: 20px; line-height: 20px; padding: 0 8px; border-radius: 999px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-secondary); font-size: 12px; font-weight: 650; }
:is(.dpm, .dpm-dialog) .cell { display: flex; flex-direction: column; gap: 8px; min-height: 96px; padding: 8px; border-radius: 10px; background: var(--dsw-alias-bg-module-platform); transition: background 160ms var(--ease), box-shadow 160ms var(--ease); }
:is(.dpm, .dpm-dialog) .cell.over { background: var(--pm-brand-soft); box-shadow: inset 0 0 0 2px var(--pm-brand); }
/* Внизу каждого этапа постоянно «Добавить карточку» (прототип v8) */
.dpm .addc { display: flex; align-items: center; gap: 6px; width: 100%; min-height: 32px; padding: 0 8px; border: 0; border-radius: 8px; background: transparent; color: var(--dsw-alias-label-secondary); font: inherit; font-size: 13px; text-align: left; cursor: pointer; transition: background 140ms var(--ease), color 140ms var(--ease); }
.dpm .addc:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm .cell.empty .addc { justify-content: center; min-height: 40px; border: 1px dashed var(--dsw-alias-border-l3); }
.dpm .cell.over .addc { visibility: hidden; }
.dpm .addc-f { display: flex; flex-direction: column; gap: 4px; animation: fadein 160ms var(--ease); }
.dpm .addc-f input { width: 100%; height: 36px; padding: 0 12px; border: 1px solid var(--pm-brand); border-radius: 8px; background: var(--pm-card); color: inherit; font: inherit; outline: 0; box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm .addc-f .hint { padding: 0 4px; font-size: 12px; color: var(--dsw-alias-label-secondary); }
@media (max-width: 720px), (pointer: coarse) { .dpm .addc { min-height: 40px; } }
:is(.dpm, .dpm-dialog) .card { display: flex; flex-direction: column; gap: 8px; padding: 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--pm-card); box-shadow: var(--pm-shadow); text-align: left; transition: border-color 200ms var(--ease), box-shadow 200ms var(--ease), transform 200ms var(--ease), opacity 160ms var(--ease); }
:is(.dpm, .dpm-dialog) .card:hover { border-color: var(--dsw-alias-border-l3); box-shadow: var(--pm-shadow-2); transform: translateY(-1px); }
:is(.dpm, .dpm-dialog) .card[aria-pressed="true"] { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
:is(.dpm, .dpm-dialog) .card.dragging { opacity: .45; }
:is(.dpm, .dpm-dialog) .card.landed { animation: land 420ms var(--ease); }
@keyframes land { 0% { transform: scale(.96); } 100% { transform: none; } }
:is(.dpm, .dpm-dialog) .card h3 { margin: 0; font-size: 15px; font-weight: 650; line-height: 1.4; word-break: break-word; }
:is(.dpm, .dpm-dialog) .card p { margin: 0; font-size: 13px; line-height: 1.5; color: var(--dsw-alias-label-secondary); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
:is(.dpm, .dpm-dialog) .foot { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
:is(.dpm, .dpm-dialog) .prog { flex: 1; min-width: 96px; display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
:is(.dpm, .dpm-dialog) .bar { flex: 1; height: 4px; border-radius: 999px; background: var(--dsw-alias-bg-module-platform); overflow: hidden; }
:is(.dpm, .dpm-dialog) .bar i { display: block; height: 100%; border-radius: 999px; background: var(--pm-brand); transition: width 400ms var(--ease); }
:is(.dpm, .dpm-dialog) .chip { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 8px; border: 1px solid transparent; border-radius: 999px; font-size: 12px; font-weight: 650; white-space: nowrap; }
:is(.dpm, .dpm-dialog) .chip svg.i { width: 12px; height: 12px; }
:is(.dpm, .dpm-dialog) .chip.warn { background: var(--pm-warn-soft); color: var(--pm-warn); border-color: var(--pm-warn-line); }
:is(.dpm, .dpm-dialog) .chip.brand { background: var(--pm-brand-soft); color: var(--pm-brand); border-color: var(--pm-brand-line); }
:is(.dpm, .dpm-dialog) .chip.plain { background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .empty-board { display: grid; place-items: center; gap: 12px; padding: 48px 16px; text-align: center; color: var(--dsw-alias-label-secondary); }

/* ── Плагин: панель деталей ── */
:is(.dpm, .dpm-dialog) .detail { width: 380px; flex: none; display: flex; flex-direction: column; border-left: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-layer-1); animation: slidein 240ms var(--ease); }
@keyframes slidein { from { opacity: 0; transform: translateX(16px); } }
:is(.dpm, .dpm-dialog) .d-h { display: flex; align-items: flex-start; gap: 8px; padding: 16px 20px 12px; border-bottom: 1px solid var(--dsw-alias-border-l2); }
:is(.dpm, .dpm-dialog) .d-h h2 { margin: 0; font-size: 18px; font-weight: 650; line-height: 1.35; word-break: break-word; }
:is(.dpm, .dpm-dialog) .d-h .sub { margin-top: 4px; font-size: 13px; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .d-b { flex: 1; overflow: auto; padding: 0 20px 16px; }
:is(.dpm, .dpm-dialog) .sec { padding: 16px 0; border-bottom: 1px solid var(--dsw-alias-border-l2); }
:is(.dpm, .dpm-dialog) .sec:last-child { border-bottom: 0; }
:is(.dpm, .dpm-dialog) .sec h3 { margin: 0 0 8px; display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .statebox { padding: 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); }
:is(.dpm, .dpm-dialog) .statebox .l { margin: 8px 0 0; font-size: 14px; line-height: 1.5; }
:is(.dpm, .dpm-dialog) .statebox .nx { margin: 8px 0 0; padding: 8px 12px; border-radius: 8px; background: var(--dsw-alias-bg-layer-1); font-size: 13px; line-height: 1.5; }
:is(.dpm, .dpm-dialog) .statebox .nx b { margin-right: 8px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
:is(.dpm, .dpm-dialog) .repo { display: flex; align-items: center; gap: 12px; padding: 8px 12px; margin-bottom: 8px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; }
:is(.dpm, .dpm-dialog) .repo .txt { flex: 1; min-width: 0; }
:is(.dpm, .dpm-dialog) .repo .nm { font-size: 14px; font-weight: 650; }
:is(.dpm, .dpm-dialog) .repo .mono { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
