.dpm-dialog #dpmStAdd { margin: 4px 0 8px; }


/* ── v0.7: маркер сессий карточки (есть активные = зелёный, все в архиве = серый; без мигания)── */
:is(.dpm, .dpm-dialog) .foot:empty { display: none; }
:is(.dpm, .dpm-dialog) .chip.ok { background: var(--pm-ok-soft); color: var(--pm-ok); }
.dpm .chip.sess { gap: 5px; }
.dpm .chip.sess .bub { position: relative; display: grid; }
.dpm .chip.sess .bub i { position: absolute; right: -2px; top: -2px; width: 6px; height: 6px; border-radius: 999px; box-shadow: 0 0 0 1.5px var(--pm-card); }
.dpm .chip.sess.on { background: var(--pm-ok-soft); color: var(--pm-ok); border-color: color-mix(in srgb, var(--pm-ok) 28%, transparent); }
.dpm .chip.sess.on .bub i { background: var(--pm-ok); }
.dpm .chip.sess.off { background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); border-color: var(--dsw-alias-border-l2); }
.dpm .chip.sess.off .bub i { background: var(--dsw-alias-label-secondary); opacity: .55; }
/* ── v0.7: заметки ── */
.dpm .note-in { display: block; width: 100%; min-height: 128px; max-height: 50vh; padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); font-size: 14px; line-height: 1.6; resize: vertical; outline: 0; field-sizing: content; }
.dpm .note-in:focus { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); background: var(--dsw-alias-bg-layer-1); }
.dpm .note-bar { display: flex; align-items: center; gap: 8px; margin-top: 8px; }
.dpm .note-bar .meta { font-variant-numeric: tabular-nums; }
.dpm .note-view { padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); font-size: 14px; line-height: 1.6; white-space: pre-wrap; word-break: break-word; }
.dpm .note-view a { color: var(--pm-brand); text-decoration: underline; text-underline-offset: 2px; word-break: break-all; }
.dpm .note-view a:hover { text-decoration-thickness: 2px; }
/* ── 0.10: длинные заметки сворачиваются (без внутренней прокрутки)── */
.dpm .note-wrap.clamp .note-view { max-height: 172px; overflow: hidden; -webkit-mask-image: linear-gradient(#000 calc(100% - 44px), transparent); mask-image: linear-gradient(#000 calc(100% - 44px), transparent); }
.dpm .note-more { margin-top: 4px; color: var(--pm-brand); }
.dpm .note-more[hidden] { display: none; }
.dpm .note-more svg.i { transition: transform 160ms var(--ease); }
.dpm .note-more[aria-expanded="true"] svg.i { transform: rotate(180deg); }
/* ── 0.10: ссылки ── */
.dpm .wl-list { display: flex; flex-direction: column; gap: 6px; }
.dpm .wl { position: relative; display: flex; align-items: center; gap: 4px; min-height: 40px; padding: 4px 4px 4px 2px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-layer-1); }
.dpm .wl:hover { border-color: var(--dsw-alias-border-l3); }
.dpm .wl .wgrip { flex: none; width: 22px; height: 28px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 6px; background: none; color: var(--dsw-alias-label-secondary); opacity: .45; cursor: grab; touch-action: none; }
.dpm .wl .wgrip svg.i { width: 14px; height: 14px; }
.dpm .wl:hover .wgrip, .dpm .wl .wgrip:focus-visible { opacity: 1; }
.dpm .wl .wl-a { flex: 1; min-width: 0; display: flex; align-items: center; gap: 8px; padding: 4px 2px; color: var(--dsw-alias-label-primary); text-decoration: none; font-size: 14px; font-weight: 600; border-radius: 6px; }
.dpm .wl .wl-a.ro { padding-left: 8px; }
.dpm .wl .wl-a svg.i { flex: none; color: var(--dsw-alias-label-secondary); }
.dpm .wl .wl-a .t { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm .wl .wl-a:hover .t { color: var(--pm-brand); text-decoration: underline; text-underline-offset: 2px; }
.dpm .wl .chip { flex: none; height: 20px; }
/* 0.20: Изменить / Удалить показывается всегда (ручка перетаскивания — по-прежнему по наведению) */
.dpm .wl .acts { display: flex; gap: 2px; flex: none; }
@media (hover: none) { .dpm .wl .acts, .dpm .wl .wgrip { opacity: 1; } }
.dpm .wl .ib.sm { width: 28px; height: 28px; }
.dpm .wl .ib.del:hover { color: #c62828; background: rgba(198, 40, 40, .08); }
body[data-ds-dark-theme] .dpm .wl .ib.del:hover { color: #ff8a80; }
.dpm .wl.lifting { opacity: .45; }
.dpm .wl.wins-before::before, .dpm .wl.wins-after::after { content: ""; position: absolute; left: 4px; right: 4px; height: 3px; border-radius: 999px; background: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); pointer-events: none; }
.dpm .wl.wins-before::before { top: -5px; }
.dpm .wl.wins-after::after { bottom: -5px; }
.dpm .wl.landed { animation: land 420ms var(--ease); }
.dpm.wdragging, .dpm.wdragging * { cursor: grabbing !important; user-select: none; }
.dpm-dialog .wl-rows { display: flex; flex-direction: column; gap: 10px; }
.dpm-dialog .wl-row { padding: 10px 12px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; }
.dpm-dialog .wl-row-h { display: flex; align-items: center; gap: 8px; min-height: 24px; margin-bottom: 4px; font-size: 12px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .wl-row-h .ib.sm { width: 28px; height: 28px; }
.dpm-dialog .wl-grid { display: grid; grid-template-columns: minmax(0, 1fr) 148px; gap: 4px 8px; align-items: end; }
.dpm-dialog .wl-grid .full { grid-column: 1 / -1; }
.dpm-dialog .wl-grid .lbl { display: block; margin: 6px 0 4px; font-size: 12px; font-weight: 600; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .wl-tnew { display: flex; gap: 4px; }
.dpm-dialog .wl-tnew .fld { min-width: 0; }
.dpm-dialog .wl-tnew .btn { flex: none; min-height: 36px; padding: 0 10px; }
.dpm-dialog .wl-err { margin: 4px 0 0; font-size: 12px; color: #c62828; }
body[data-ds-dark-theme] .dpm-dialog .wl-err { color: #ff8a80; }
.dpm-dialog .wl-add { margin-top: 10px; }
@media (max-width: 720px) { .dpm-dialog .wl-grid { grid-template-columns: 1fr; } }
/* ── v0.7: файлы ── */
.dpm .frow-f { display: flex; align-items: flex-start; gap: 10px; padding: 8px 6px 8px 10px; margin-bottom: 6px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; }
.dpm .frow-f > svg.i { margin-top: 2px; color: var(--dsw-alias-label-secondary); }
.dpm .frow-f .txt { flex: 1; min-width: 0; }
.dpm .frow-f .nm { font-size: 14px; font-weight: 600; word-break: break-all; }
.dpm .frow-f .mono { display: block; margin-top: 2px; line-height: 1.45; }
.dpm .frow-f .chip { height: 20px; margin-top: 6px; }
.dpm .frow-f.gone { border-style: dashed; }
.dpm .frow-f.gone > svg.i { color: var(--pm-warn); }
.dpm .frow-f.gone .nm { color: var(--dsw-alias-label-secondary); text-decoration: line-through; }

/* ── 0.8 архивирование карточки (прототип v19) ── */
/* Шапка группы не переносится на новую строку: имя/счётчики могут усекаться, кнопки справа всегда в один ряд, «Карточки в архиве» вплотную к «Новой сессии» */
@media (min-width: 721px) {
  .dpm .lane-h { flex-wrap: nowrap; }
  .dpm .lane-hit { flex: 1 1 0; flex-wrap: nowrap; overflow: hidden; }
  .dpm .lane-hit .meta { flex: 0 1000 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
  .dpm .lane-hit h2 { flex: 0 1 auto; min-width: 48px; }
  .dpm .lane-hit h2 .tg { min-width: 0; }
  .dpm .lane-hit h2 .nm { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .dpm .lane-hit .chip { flex: none; }
  .dpm .lane-h > .btn, .dpm .lane-h > .ib { flex: none; }
}
.dpm .card { position: relative; }
.dpm .card h3 { padding-right: 22px; }
.dpm .card .carc { position: absolute; top: 6px; right: 6px; width: 28px; height: 28px; opacity: 0; transition: opacity 120ms var(--ease), background 120ms var(--ease), color 120ms var(--ease); }
.dpm .card:hover .carc, .dpm .card:focus-within .carc, .dpm .card .carc:focus-visible { opacity: 1; }
@media (pointer: coarse) { .dpm .card .carc { opacity: 1; } }
.dpm .card.leaving { animation: dpmleave 220ms var(--ease) forwards; pointer-events: none; }
@keyframes dpmleave { to { opacity: 0; transform: scale(.94) translateY(-4px); } }
.dpm .btn .cnt { min-width: 20px; height: 20px; padding: 0 6px; border-radius: 999px; background: var(--dsw-alias-bg-module-platform); font-size: 12px; font-weight: 650; line-height: 20px; text-align: center; color: var(--dsw-alias-label-secondary); font-variant-numeric: tabular-nums; }
.dpm .lane-h .btn[aria-expanded="true"] { background: var(--pm-brand-soft); color: var(--pm-brand); }
.dpm .lane-h .btn[aria-expanded="true"] .cnt { background: var(--pm-brand); color: var(--pm-brand-ink); }
.dpm .atray { margin: 0 12px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); overflow: hidden; outline: 2px dashed transparent; outline-offset: -2px; animation: dpmtray 160ms var(--ease); transition: outline-color 120ms var(--ease); }
@keyframes dpmtray { from { opacity: 0; transform: translateY(-4px); } }
.dpm .lane.collapsed .atray { display: none; }
.dpm .atray-h { display: flex; align-items: center; gap: 8px; padding: 4px 4px 4px 12px; border-bottom: 1px solid var(--dsw-alias-border-l2); font-size: 12px; font-weight: 600; color: var(--dsw-alias-label-secondary); }
.dpm .atray-l { max-height: 296px; overflow: auto; padding: 6px; }
.dpm .arow { display: flex; align-items: center; gap: 8px; min-height: 40px; padding: 3px 3px 3px 7px; border: 1px solid transparent; border-radius: 8px; cursor: pointer; transition: border-color 200ms var(--ease), box-shadow 200ms var(--ease); }
.dpm .arow + .arow { margin-top: 2px; }
.dpm .arow:hover { background: var(--pm-select); }
/* выбрано = то же, что у активной карточки: синяя рамка + светло-синий ореол */
.dpm .arow[aria-current="true"] { background: var(--pm-card); border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm .arow[aria-current="true"] .nm { font-weight: 600; }
.dpm .arow .txt { flex: 1; min-width: 0; display: flex; align-items: baseline; gap: 12px; }
.dpm .arow .nm { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; font-weight: 500; color: var(--dsw-alias-label-primary); }
.dpm .arow .sub { flex: 1 1 0; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm .arow.leaving { animation: dpmrowout 220ms var(--ease) forwards; }
@keyframes dpmrowout { to { opacity: 0; transform: translateX(12px); } }
.dpm .arow.landed { animation: lland 700ms var(--ease); }
.dpm .ib.rst { flex: none; width: 28px; height: 28px; opacity: 0; }
.dpm .arow:hover .ib.rst, .dpm .arow:focus-within .ib.rst, .dpm .arow[aria-current="true"] .ib.rst, .dpm .ib.rst:focus-visible { opacity: 1; }
@media (pointer: coarse) { .dpm .ib.rst { opacity: 1; } }
/* Список — скролл-контейнер: подсказка встаёт в одну строку слева от иконки, последняя строка не обрезается */
.dpm .ib.rst .tip { top: 50%; right: calc(100% + 6px); transform: translateY(-50%); }
.dpm.carddrag .atray { outline-color: var(--dsw-alias-border-l3); }
.dpm .atray.over { outline: 2px solid var(--pm-brand); }
.dpm .atray-drop { display: none; align-items: center; justify-content: center; min-height: 40px; margin: 0 0 4px; font-size: 13px; color: var(--dsw-alias-label-secondary); }
.dpm.carddrag .atray-drop { display: flex; }
.dpm .atray.over .atray-drop { color: var(--pm-brand); }
.dpm.carddrag .atray-empty { display: none; }
.dpm .atray-empty { margin: 0; padding: 20px 12px; text-align: center; font-size: 13px; color: var(--dsw-alias-label-secondary); }
/* Детали архива: под заголовком тонкая строка состояния, заметки + кнопка восстановления в одной строке; в тексте нет точек входа для действий */
.dpm .arch-bar { display: flex; align-items: center; gap: 12px; padding: 8px 12px 8px 20px; border-bottom: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-module-platform); font-size: 13px; color: var(--dsw-alias-label-secondary); }
.dpm .arch-bar .txt { flex: 1; min-width: 0; }
.dpm .arch-bar b { font-weight: 650; color: var(--dsw-alias-label-primary); }
.dpm .detail.ro .step, .dpm .detail.ro .task { cursor: default; }
.dpm .detail.ro .step:hover .nd { border-color: var(--dsw-alias-border-l3); }
.dpm .detail.ro .step.past:hover .nd, .dpm .detail.ro .step.cur:hover .nd { border-color: var(--pm-brand); }
.dpm .lsess .acts { display: flex; gap: 2px; flex: none; margin-left: auto; }
.dpm-toasts .toast .ta { pointer-events: auto; margin-left: 8px; padding: 2px 8px; border: 0; border-radius: 6px; background: rgba(255, 255, 255, .16); color: inherit; font: inherit; font-size: 13px; font-weight: 650; cursor: pointer; }
body[data-ds-dark-theme] .dpm-toasts .toast .ta { background: rgba(0, 0, 0, .12); }
.dpm-dialog .cf-list { margin: 8px 0 0; padding-left: 18px; font-size: 13px; color: var(--dsw-alias-label-secondary); }

/* ── 0.9 главная кнопка общей панели «Проектная доска» (прототип v15-panel2)──
   строка хоста = button:has(> * > .dpm-entry) (учитывается только собственный блок иконки плагина, без хешированных классов хоста); при потере правила вырождается в обычную строку с иконкой. */
@property --dpm-rim { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
button:has(.dpm-entry) {
  --dpm-a: #2f5fcc; --dpm-b: #0a7d9c; --dpm-ink: #1f4fb8; --dpm-side: var(--dsw-specific-sidebar-fill, #f9fafb);
  --ease: cubic-bezier(.2, .8, .2, 1);
  position: relative; isolation: isolate; overflow: hidden; min-height: 42px; margin-block: 2px 4px; border-radius: 12px;
  color: var(--dpm-ink) !important; font-weight: 650;
  background: linear-gradient(115deg, color-mix(in srgb, var(--dpm-a) 11%, var(--dpm-side)) 0%, color-mix(in srgb, var(--dpm-b) 13%, var(--dpm-side)) 100%) !important;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dpm-a) 26%, transparent), 0 1px 2px rgba(15, 17, 21, .05);
  transition: transform 220ms var(--ease), box-shadow 260ms var(--ease), color 220ms var(--ease);
}
body[data-ds-dark-theme] button:has(.dpm-entry) { --dpm-ink: #b9ccff; --dpm-side: var(--dsw-specific-sidebar-fill, #1c1c1e); box-shadow: inset 0 0 0 1px color-mix(in srgb, #8fb0ff 30%, transparent); }
/* Слот иконки хоста должен оставаться static, слой свечения/бейдж только так позиционируется по всей строке; текст заголовка лежит поверх слоя свечения */
button:has(.dpm-entry) > :has(.dpm-entry), button:has(.dpm-entry) > :has(.dpm-entry) :has(.dpm-entry) { position: static !important; }
button:has(.dpm-entry) > :not(:has(.dpm-entry)) { position: relative; z-index: 2; }
/* Полоса иконок: уголок позиционируется по блоку иконки */
button:has(.dpm-entry.rail) > :has(.dpm-entry) { position: relative !important; }
button:has(.dpm-entry):hover { transform: translateY(-1px); background: linear-gradient(115deg, color-mix(in srgb, var(--dpm-a) 16%, var(--dpm-side)) 0%, color-mix(in srgb, var(--dpm-b) 19%, var(--dpm-side)) 100%) !important; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dpm-a) 40%, transparent), 0 6px 18px color-mix(in srgb, var(--dpm-a) 22%, transparent); }
button:has(.dpm-entry):active { transform: translateY(0) scale(.975); transition-duration: 90ms; }
button:has(.dpm-entry[data-active="true"]) { color: #ffffff !important; background: linear-gradient(115deg, var(--dpm-a) 0%, var(--dpm-b) 100%) !important; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .22), 0 8px 22px color-mix(in srgb, var(--dpm-a) 38%, transparent); transform: none; }
button:has(.dpm-entry[data-active="true"]):hover { box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .3), 0 10px 26px color-mix(in srgb, var(--dpm-b) 42%, transparent); }
button:has(.dpm-entry):focus-visible { outline: 2px solid var(--dpm-a); outline-offset: 2px; }
/* Блок иконки (хост даёт слот 16/18px, блок плагина 24px) */
.dpm-entry { position: static; display: inline-grid; place-items: center; width: 24px; height: 24px; margin: -4px -2px; }
.dpm-entry .pgw { position: relative; z-index: 2; width: 24px; height: 24px; }
.dpm-entry .pg { position: relative; width: 24px; height: 24px; display: grid; place-items: center; overflow: hidden; border-radius: 8px; color: #ffffff; background: linear-gradient(135deg, var(--dpm-a), var(--dpm-b)); box-shadow: 0 2px 8px color-mix(in srgb, var(--dpm-a) 35%, transparent), inset 0 0 0 1px rgba(255, 255, 255, .2); transition: background 220ms var(--ease), color 220ms var(--ease), transform 160ms var(--ease); }
.dpm-entry .pgi { width: 16px; height: 16px; overflow: visible; }
.dpm-entry .pgi rect { fill: currentColor; stroke: none; transform-box: fill-box; transform-origin: 50% 0; }
.dpm-entry .pgi .b2 { fill: color-mix(in srgb, currentColor 55%, transparent); }
.dpm-entry .pgi .drop { opacity: 0; fill: var(--dpm-a); transform-origin: 50% 50%; }
.dpm-entry[data-active="true"] .pg { background: rgba(255, 255, 255, .95); color: var(--dpm-a); box-shadow: 0 2px 10px rgba(20, 10, 60, .25); }
.dpm-entry[data-active="true"] .pgi .b2 { fill: color-mix(in srgb, var(--dpm-a) 45%, transparent); }
.dpm-entry[data-active="true"] .pgi .drop { opacity: 1; }
button:has(.dpm-entry):hover .pgi .b1 { animation: dpm-eq 560ms var(--ease) both; }
button:has(.dpm-entry):hover .pgi .b2 { animation: dpm-eq 560ms 70ms var(--ease) both; }
button:has(.dpm-entry):hover .pgi .b3 { animation: dpm-eq 560ms 140ms var(--ease) both; }
@keyframes dpm-eq { 0%, 100% { transform: scaleY(1); } 35% { transform: scaleY(.55); } 70% { transform: scaleY(1.12); } }
/* Слой свечения: на всю строку хоста */
.dpm-entry .hfx { position: absolute; inset: 0; z-index: 1; border-radius: inherit; pointer-events: none; overflow: hidden; }
.dpm-entry .hfx .rim { position: absolute; inset: 0; border-radius: 12px; padding: 1.5px; background: conic-gradient(from var(--dpm-rim), transparent 0 62%, var(--dpm-a) 76%, #3fd0ea 86%, transparent 96%); -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask-composite: exclude; opacity: 0; }
button:has(.dpm-entry):hover .hfx .rim { animation: dpm-rim 1100ms var(--ease) both; }
@keyframes dpm-rim { 0% { opacity: 0; --dpm-rim: 0deg; } 15% { opacity: 1; } 85% { opacity: 1; } 100% { opacity: 0; --dpm-rim: 360deg; } }
.dpm-entry .hfx .spot { position: absolute; inset: 0; background: radial-gradient(120px circle at var(--dpm-mx, 50%) var(--dpm-my, 50%), rgba(255, 255, 255, .55), transparent 60%); opacity: 0; transition: opacity 200ms var(--ease); }
button:has(.dpm-entry):hover .hfx .spot { opacity: .55; }
button:has(.dpm-entry[data-active="true"]):hover .hfx .spot { opacity: .28; }
.dpm-entry .hfx .sheen { position: absolute; top: -20%; bottom: -20%; left: 0; width: 38%; background: linear-gradient(100deg, transparent, rgba(255, 255, 255, .55), transparent); transform: translateX(-120%) skewX(-16deg); opacity: 0; }
button:has(.dpm-entry):hover .hfx .sheen { animation: dpm-sheen 900ms 80ms var(--ease) both; }
.dpm-entry.fx .hfx .sheen { animation: dpm-sheen 900ms 180ms var(--ease) both; }
@keyframes dpm-sheen { 0% { opacity: 1; transform: translateX(-120%) skewX(-16deg); } 100% { opacity: 1; transform: translateX(380%) skewX(-16deg); } }
.dpm-entry .hfx .ripple { position: absolute; left: var(--dpm-rx, 50%); top: var(--dpm-ry, 50%); width: 16px; height: 16px; margin: -8px 0 0 -8px; border-radius: 50%; background: rgba(255, 255, 255, .55); opacity: 0; }
.dpm-entry.fx .hfx .ripple { animation: dpm-ripple 650ms var(--ease) both; }
@keyframes dpm-ripple { 0% { opacity: .7; transform: scale(0); } 100% { opacity: 0; transform: scale(22); } }
.dpm-entry .pgw::before { content: ""; position: absolute; inset: -3px; border-radius: 11px; box-shadow: 0 0 0 2px #ffffff; opacity: 0; pointer-events: none; }
.dpm-entry.fx .pgw::before { animation: dpm-burst 620ms var(--ease) both; }
.dpm-entry.fx .pgi .drop { animation: dpm-drop 520ms cubic-bezier(.3, 1.6, .5, 1) both; }
@keyframes dpm-burst { 0% { opacity: .55; transform: scale(.8); } 100% { opacity: 0; transform: scale(1.75); } }
@keyframes dpm-drop { 0% { opacity: 0; transform: translateY(-15px) scale(.6); } 60% { opacity: 1; } 100% { opacity: 1; transform: none; } }
/* Бейдж: число карточек в работе */
.dpm-entry .hbadge { position: absolute; right: 8px; top: 50%; z-index: 2; display: inline-flex; align-items: center; gap: 4px; height: 22px; padding: 0 8px; border-radius: 999px; transform: translateY(-50%); background: color-mix(in srgb, var(--dpm-a) 14%, var(--dsw-alias-bg-layer-1, #ffffff)); color: var(--dpm-ink); font-size: 12px; font-weight: 650; line-height: 1; font-variant-numeric: tabular-nums; white-space: nowrap; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dpm-a) 22%, transparent); }
.dpm-entry .hbadge i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; opacity: .75; }
.dpm-entry[data-active="true"] .hbadge { background: rgba(255, 255, 255, .2); color: #ffffff; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .28); }
.dpm-entry.fx .hbadge { animation: dpm-pop 520ms 260ms cubic-bezier(.3, 1.6, .5, 1) both; }
@keyframes dpm-pop { 0% { transform: translateY(-50%) scale(.6); } 100% { transform: translateY(-50%) scale(1); } }
/* Сайдбар сжат в полосу иконок (хост даёт слот 18px): градиентный квадрат + красный числовой бейдж */
button:has(.dpm-entry.rail) { min-height: 0; margin-block: 0; overflow: visible; background: transparent !important; box-shadow: none !important; }
button:has(.dpm-entry.rail):hover { background: var(--dsw-alias-interactive-bg-hover, rgba(15, 17, 21, .06)) !important; transform: none; }
.dpm-entry.rail { position: relative; }
.dpm-entry.rail .hfx { display: none; }
.dpm-entry.rail .hbadge { right: -9px; top: -9px; z-index: 3; height: 16px; min-width: 16px; padding: 0 4px; justify-content: center; transform: none; font-size: 11px; background: #e5484d; color: #ffffff; box-shadow: 0 0 0 2px var(--dpm-side); }
.dpm-entry.rail .hbadge i, .dpm-entry.rail .hbadge .hl { display: none; }
.dpm-entry.rail.fx .hbadge { animation: none; }
/* 0.11: число активных сессий и направляющая иерархии в строке группы сайдбара (правила по id строки генерирует sidebar.ts, здесь только цвета и анимация) */
:root { --dpm-cnt-bg: #eaf0fd; --dpm-cnt-ink: #2f5fcc; --dpm-guide: rgba(15, 17, 21, .14); }
body[data-ds-dark-theme] { --dpm-cnt-bg: #1d2a4a; --dpm-cnt-ink: #8fb0ff; --dpm-guide: rgba(255, 255, 255, .18); }
@keyframes dpm-cnt-bump { 40% { transform: scale(1.25); } }
/* 0.12: в области проекта хост скрывает сессии «ещё без диалога», плагин дорисовывает их строки (размеры как у строк сессий хоста: высота 32px, слот 16px, заголовок 14px) */
.dpm-blank-w { display: block; }
.dpm-blank { box-sizing: border-box; display: flex; align-items: center; width: -webkit-fill-available; width: stretch; height: 32px; padding: 0 8px; padding-inline-start: calc(8px + var(--dsh-workspace-indent, 0px)); border: 0; border-radius: var(--dsw-radius-md, 12px); background: transparent; color: var(--dsw-alias-label-secondary, #61666b); font: inherit; text-align: left; cursor: pointer; }
.dpm-blank:hover { background: var(--dsw-alias-interactive-bg-hover, rgba(15, 17, 21, .06)); color: var(--dsw-alias-label-primary, #0f1115); }
.dpm-blank:focus-visible { outline: 2px solid var(--dsw-alias-state-business-primary, #2f5fcc); outline-offset: -2px; }
.dpm-blank-s { width: 16px; height: 20px; flex: none; }
.dpm-blank-t { flex: 1; min-width: 0; margin: 0 6px 0 4px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; line-height: 20px; }
.dpm-blank-tag { flex: none; height: 18px; padding: 0 6px; border: 1px dashed var(--dsw-alias-border-l3, rgba(0, 0, 0, .14)); border-radius: 6px; font-size: 11px; line-height: 16px; color: var(--dsw-alias-label-tertiary, #81858c); }
/* 0.13: дорисованную пустую строку сессии можно удалить (по наведению / по фокусу клавиатуры появляется кнопка удаления, метка «Не начато» уступает место) */
.dpm-blank-w.can-del { position: relative; }
.dpm-blank-del { position: absolute; top: 4px; right: 4px; width: 24px; height: 24px; display: none; place-items: center; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--dsw-alias-label-secondary, #61666b); cursor: pointer; }
.dpm-blank-del svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dpm-blank-w.can-del:hover .dpm-blank-del, .dpm-blank-w.can-del:focus-within .dpm-blank-del { display: grid; }
.dpm-blank-w.can-del:hover .dpm-blank-tag, .dpm-blank-w.can-del:focus-within .dpm-blank-tag { visibility: hidden; }
.dpm-blank-del:hover { color: #c62828; background: rgba(198, 40, 40, .08); }
body[data-ds-dark-theme] .dpm-blank-del:hover { color: #ff8a80; background: rgba(255, 138, 128, .1); }
.dpm-blank-del:focus-visible { display: grid; outline: 2px solid var(--dsw-alias-state-business-primary, #2f5fcc); outline-offset: -2px; }
@media (hover: none) { .dpm-blank-w.can-del .dpm-blank-del { display: grid; } .dpm-blank-w.can-del .dpm-blank-tag { visibility: hidden; } }
.dpm .lsess .ib.sdel:hover { color: #c62828; background: rgba(198, 40, 40, .08); }
body[data-ds-dark-theme] .dpm .lsess .ib.sdel:hover { color: #ff8a80; }
/* 0.13: строка заголовка «Ссылки»: «Управление типами» + «Добавить ссылку» */
.dpm .h3-acts { display: inline-flex; align-items: center; gap: 4px; flex: none; }
/* 0.13: управление типами */
.dpm-dialog .ty-list { display: flex; flex-direction: column; gap: 6px; margin: 0; padding: 0; list-style: none; }
.dpm-dialog .ty-row { display: flex; align-items: center; gap: 8px; min-height: 40px; padding: 4px 4px 4px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; }
.dpm-dialog .ty-row .nm { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }
.dpm-dialog .ty-row .use { flex: none; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .ty-row .ib.sm { width: 28px; height: 28px; }
.dpm-dialog .ty-row.editing { padding: 4px; }
.dpm-dialog .ty-row.editing .fld { flex: 1; min-width: 0; height: 32px; }
.dpm-dialog .ty-list > .wl-err { list-style: none; }
.dpm-dialog .ty-add { display: flex; gap: 8px; margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--dsw-alias-border-l2); }
.dpm-dialog .ty-add .fld { flex: 1; min-width: 0; }
.dpm-dialog .ty-add .btn { flex: none; }
@media (prefers-reduced-motion: reduce) {
  [data-row-key]::after { animation: none !important; }
  button:has(.dpm-entry), button:has(.dpm-entry):hover { transform: none; }
  .dpm-entry *, .dpm-entry *::before { animation: none !important; transition: none !important; }
}

/* ── 0.14: репозитории карточки / репозитории-кандидаты / сортировка типов / дубли ссылок ── */
:is(.dpm, .dpm-dialog) .repo .from { flex: none; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm .detail .ar-empty { margin: 0; padding: 14px 16px; border: 1px dashed var(--dsw-alias-border-l3); border-radius: 10px; text-align: center; font-size: 13px; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .pk .when { flex: none; align-self: center; margin-left: auto; font-size: 12px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.dpm-dialog .ar-list { max-height: 232px; }
.dpm-dialog .ar-sec .btn:disabled { opacity: .5; cursor: default; }
.dpm-dialog .ty-list { position: relative; }
.dpm-dialog .ty-row { padding-left: 4px; }
.dpm-dialog .ty-row .ty-grip { cursor: grab; touch-action: none; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .ty-row.lifting { opacity: .45; }
.dpm-dialog .ty-row.landed { animation: dpm-landed 450ms ease-out; }
@keyframes dpm-landed { 0% { background: var(--pm-brand-soft); } }
/* Линия места вставки: отдельный элемент, рисуется ровно в промежутке между двумя типами, без обводки элемента типа */
.dpm-dialog .drop-line { position: absolute; left: 4px; right: 4px; height: 2px; margin-top: -1px; border-radius: 2px; background: var(--pm-brand); pointer-events: none; list-style: none; }
.dpm-dialog .drop-line::before, .dpm-dialog .drop-line::after { content: ""; position: absolute; top: -3px; width: 8px; height: 8px; box-sizing: border-box; border: 2px solid var(--pm-brand); border-radius: 50%; background: var(--dsw-alias-bg-layer-1); }
.dpm-dialog .drop-line::before { left: -4px; }
.dpm-dialog .drop-line::after { right: -4px; }
.dpm-dialog .drop-line[hidden] { display: none; }
.dpm-dialog .wl-dup { margin-top: 8px; padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); }
.dpm-dialog .wl-dup .h { margin: 0 0 6px; font-size: 13px; font-weight: 650; }
.dpm-dialog .wl-dup dl { display: grid; grid-template-columns: 64px minmax(0, 1fr); gap: 2px 8px; margin: 0; font-size: 13px; }
.dpm-dialog .wl-dup dt { color: var(--dsw-alias-label-secondary); }
.dpm-dialog .wl-dup dd { margin: 0; word-break: break-all; }
.dpm-dialog .wl-dup .a { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
.dpm-dialog #dpmWlOk:disabled { opacity: .5; cursor: default; }

/* ── 0.15 диалог добавления репозитория: верх закреплён (заголовок + поиск)/ кандидатов 2 : выбрано 1 (списки прокручиваются независимо)/ нижние кнопки закреплены ── */
.dpm-dialog.ar-dlg { height: min(760px, calc(100vh - 48px)); }
.dpm-dialog.ar-dlg[open] > form { display: flex; flex-direction: column; height: 100%; }
.dpm-dialog.ar-dlg .ar-head { flex: none; padding: 20px 20px 12px; border-bottom: 1px solid var(--dsw-alias-border-l2); }
.dpm-dialog.ar-dlg .ar-head h2 { margin: 0; font-size: 16px; font-weight: 650; line-height: 1.4; }
.dpm-dialog.ar-dlg .ar-head p { margin: 4px 0 12px; font-size: 13px; color: var(--dsw-alias-label-secondary); }
.dpm-dialog .ar-cand, .dpm-dialog .ar-picked { min-height: 0; display: flex; flex-direction: column; }
.dpm-dialog .ar-cand { flex: 2 1 0; }
.dpm-dialog .ar-picked { flex: 1 1 0; border-top: 1px solid var(--dsw-alias-border-l2); background: var(--dsw-alias-bg-module-platform); }
.dpm-dialog .ar-h { flex: none; display: flex; align-items: center; gap: 8px; padding: 12px 20px 8px; font-size: 14px; font-weight: 650; }
.dpm-dialog .ar-h .meta { font-weight: 400; }
.dpm-dialog .ar-scroll { flex: 1; min-height: 0; overflow: auto; padding: 0 20px 12px; overscroll-behavior: contain; }
.dpm-dialog .ar-picked .dlg-f { flex: none; padding: 12px 20px 16px; border-top: 1px solid var(--dsw-alias-border-l2); }
.dpm-dialog .ar-scroll .ar-list { max-height: none; overflow: visible; margin-top: 0; }
.dpm-dialog .ar-scroll .pk-list { margin-top: 0; }
/* Заголовок группы прилипает: sticky внутри контейнера групп → Следующий заголовок выталкивает предыдущий; при прилипании снизу появляется тень, пояснение скрывается */
.dpm-dialog .ar-grp + .ar-grp { margin-top: 4px; }
.dpm-dialog .ar-sub { position: sticky; top: 0; z-index: 2; display: flex; align-items: center; gap: 8px; margin: 0 -20px; padding: 8px 20px 6px; background: var(--dsw-alias-bg-layer-1); font-size: 13px; font-weight: 600; color: var(--dsw-alias-label-secondary); transition: box-shadow 160ms var(--ease); }
.dpm-dialog .ar-sub .meta { font-size: 12px; font-weight: 400; }
.dpm-dialog .ar-sub.stuck { box-shadow: 0 1px 0 var(--dsw-alias-border-l2), 0 6px 12px -8px rgba(15, 17, 21, .18); }
body[data-ds-dark-theme] .dpm-dialog .ar-sub.stuck { box-shadow: 0 1px 0 var(--dsw-alias-border-l2), 0 6px 12px -8px rgba(0, 0, 0, .6); }
.dpm-dialog .ar-sub.stuck .tail { display: none; }
.dpm-dialog .ar-jump { display: inline-flex; align-items: center; gap: 6px; min-height: 28px; margin-left: -6px; padding: 0 6px; border: 0; border-radius: 8px; background: transparent; color: inherit; font: inherit; cursor: pointer; }
.dpm-dialog .ar-jump:hover { background: var(--pm-select); color: var(--dsw-alias-label-primary); }
.dpm-dialog .ar-jump .chev { width: 14px; height: 14px; opacity: 0; transform: rotate(180deg); transition: opacity 160ms var(--ease); }
.dpm-dialog .ar-sub.stuck .ar-jump .chev { opacity: .7; }
.dpm-dialog .ar-spy { display: inline-flex; gap: 2px; padding: 2px; border-radius: 10px; background: var(--dsw-alias-bg-module-platform); }
.dpm-dialog .ar-spy button { min-height: 26px; padding: 0 10px; border: 0; border-radius: 8px; background: transparent; color: var(--dsw-alias-label-secondary); font-size: 12px; font-weight: 600; cursor: pointer; transition: background 160ms var(--ease), color 160ms var(--ease); }
.dpm-dialog .ar-spy button:hover { color: var(--dsw-alias-label-primary); }
.dpm-dialog .ar-spy button[aria-current="true"] { background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); box-shadow: var(--pm-shadow); }
.dpm-dialog .ar-spy button:disabled { opacity: .45; cursor: default; }
.dpm-dialog .pk.flash, .dpm-dialog .rp-row.fresh { animation: dpm-fresh 900ms var(--ease); }
@keyframes dpm-fresh { 0%, 40% { background: var(--pm-brand-soft); } }
/* ── 0.15 файлы: выбор файлов / вставка пути ── */
.dpm .fseg { display: inline-flex; gap: 2px; padding: 2px; border-radius: 10px; background: var(--dsw-alias-bg-module-platform); }
.dpm .fseg .btn.sm { min-height: 26px; }
.dpm .fseg .btn.sm:hover { background: var(--dsw-alias-bg-layer-1); }
.dpm .fp { margin-top: 8px; padding: 12px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 12px; background: var(--dsw-alias-bg-module-platform); }
.dpm .fp label { display: block; margin-bottom: 6px; font-size: 13px; font-weight: 600; }
.dpm .fp textarea { width: 100%; min-height: 64px; padding: 8px 10px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); font: 12px/1.6 "SF Mono", Menlo, monospace; resize: vertical; outline: 0; }
.dpm .fp textarea:focus { border-color: var(--pm-brand); }
.dpm .fp-chk { display: flex; flex-direction: column; gap: 4px; margin: 8px 0 0; padding: 0; list-style: none; }
.dpm .fp-chk li { display: grid; grid-template-columns: 16px minmax(0, 1fr); column-gap: 6px; font-size: 12px; line-height: 1.5; }
.dpm .fp-chk li svg.i { width: 16px; height: 16px; margin-top: 1px; }
.dpm .fp-chk .p { min-width: 0; word-break: break-all; font-family: "SF Mono", Menlo, monospace; }
.dpm .fp-chk .why { grid-column: 2; }
.dpm .fp-chk .ok svg.i, .dpm .fp-chk .ok .why { color: var(--pm-ok); }
.dpm .fp-chk .bad svg.i, .dpm .fp-chk .bad .why { color: #c62828; }
body[data-ds-dark-theme] .dpm .fp-chk .bad svg.i, body[data-ds-dark-theme] .dpm .fp-chk .bad .why { color: #ff8a80; }
.dpm .fp-chk .skip svg.i, .dpm .fp-chk .skip .why { color: var(--dsw-alias-label-secondary); }
.dpm .fp-bar { display: flex; align-items: center; gap: 8px; margin-top: 10px; }
.dpm .note-bar [hidden] { display: none; }
/* ── 0.15 доска: синхронизация + первый скелетон ── */
.dpm .pm-top h1 { display: flex; align-items: center; gap: 10px; }
.dpm .pm-sync { display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 8px; border-radius: 999px; background: var(--dsw-alias-bg-module-platform); color: var(--dsw-alias-label-secondary); font-size: 12px; font-weight: 500; opacity: 0; transition: opacity 200ms var(--ease); pointer-events: none; }
.dpm .pm-sync.on { opacity: 1; }
.dpm .pm-sync .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--pm-brand); animation: dpm-pulse 1s ease-in-out infinite; }
@keyframes dpm-pulse { 50% { opacity: .3; } }
.dpm .skel-lane { padding: 12px; }
.dpm .skel-h { width: 160px; height: 18px; margin-bottom: 12px; border-radius: 6px; }
.dpm .skel-row { display: grid; grid-template-columns: repeat(3, minmax(160px, 1fr)); gap: 8px; }
.dpm .skel { height: 84px; border-radius: 10px; }
.dpm .skel, .dpm .skel-h { background: linear-gradient(90deg, var(--dsw-alias-bg-module-platform) 0%, var(--pm-select) 50%, var(--dsw-alias-bg-module-platform) 100%) 0 0 / 200% 100%; animation: dpm-shimmer 1.2s linear infinite; }
@keyframes dpm-shimmer { to { background-position: -200% 0; } }

/* 0.16 точка входа проекта на диске */
.dpm .lf-note { display: flex; align-items: center; gap: 8px; margin: 0 0 16px; padding: 8px 12px; border: 1px solid var(--dsw-alias-border-l2); border-radius: 10px; background: var(--dsw-alias-bg-module-platform); font-size: 13px; color: var(--dsw-alias-label-secondary); }
.dpm .lf-note > .i { flex: none; width: 16px; height: 16px; }
.dpm .lf-note .txt { flex: 1; min-width: 0; line-height: 1.5; }
.dpm .lf-note b { color: var(--dsw-alias-label-primary); font-weight: 600; }
.dpm .lf-note code { font-size: 12px; word-break: break-all; }
.dpm .mem-act { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 8px; }
.dpm .mem-act .hint { flex: 1 1 140px; min-width: 0; margin: 0; font-size: 12px; line-height: 1.45; color: var(--dsw-alias-label-secondary); }



/* ══ 0.19 карточка сессии (прототип v35): привязана = тот же светло-синий, что у кнопки доски; не привязана = нейтральный светло-серый ══ */
.dpm-sic { --pm-sic-off-bg: #f3f4f6; --pm-sic-off-line: rgba(0, 0, 0, .12); --pm-on-chip: rgba(255, 255, 255, .72); --pm-on-grp: rgba(255, 255, 255, .58); --pm-bad: #c43c3c; --pm-guide: rgba(15, 17, 21, .14); font-size: 13px; line-height: 1.5; padding: 0; overflow: hidden; box-shadow: var(--pm-shadow); transition: box-shadow 240ms var(--ease), border-color 240ms var(--ease); }
body[data-ds-dark-theme] .dpm-sic { --pm-sic-off-bg: #29292b; --pm-sic-off-line: rgba(255, 255, 255, .14); --pm-on-chip: rgba(255, 255, 255, .07); --pm-on-grp: rgba(0, 0, 0, .2); --pm-bad: #ff8a8a; --pm-guide: rgba(255, 255, 255, .18); }
.dpm-sic[hidden] { display: none !important; }
.dpm-sic.on { background: linear-gradient(135deg, var(--pm-brand-soft) 0%, color-mix(in srgb, var(--pm-brand-soft) 42%, var(--dsw-alias-bg-layer-1)) 100%); border-color: var(--pm-brand-line); }
.dpm-sic.off { background: var(--pm-sic-off-bg); border-color: var(--pm-sic-off-line); }
.dpm-sic.open { box-shadow: var(--pm-shadow-2); }
.dpm-sic button, .dpm-sic input { font: inherit; color: inherit; }
.dpm-sic button { cursor: pointer; }
.dpm-sic :focus-visible { outline: 2px solid var(--pm-brand); outline-offset: 2px; border-radius: 8px; }
.dpm-sic .mono { font: 12px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace; color: var(--dsw-alias-label-secondary); }
.dpm-sic .sic-h { position: relative; display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 6px 0 10px; }
.dpm-sic .sic-h .tgl { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0; height: 100%; padding: 0; border: 0; background: transparent; text-align: left; }
.dpm-sic .sic-h .tgl:focus-visible { outline-offset: -2px; }
.dpm-sic .crumb { display: flex; align-items: center; gap: 6px; flex: none; max-width: 38%; min-width: 0; font-size: 13px; font-weight: 650; }
.dpm-sic .crumb .g { color: var(--dsw-alias-label-secondary); font-weight: 500; white-space: nowrap; }
.dpm-sic.on .crumb .g { color: color-mix(in srgb, var(--pm-brand) 55%, var(--dsw-alias-label-secondary)); }
.dpm-sic .crumb .t { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic .crumb .sl { color: var(--dsw-alias-border-l3); }
.dpm-sic .pills { display: flex; align-items: center; gap: 6px; flex: 1; min-width: 0; overflow: hidden; }
.dpm-sic .pill { display: inline-flex; align-items: center; gap: 5px; flex: none; height: 24px; padding: 0 8px; border-radius: 999px; background: var(--pm-on-chip); font-size: 12px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.dpm-sic .pill b { font-weight: 650; color: var(--dsw-alias-label-primary); font-variant-numeric: tabular-nums; }
.dpm-sic .pill svg.i { width: 13px; height: 13px; }
.dpm-sic .pill.mem { background: var(--dsw-alias-bg-layer-1); color: var(--pm-brand); box-shadow: inset 0 0 0 1px var(--pm-brand-line); }
.dpm-sic .pill.mem b { color: var(--pm-brand); }
.dpm-sic .pill .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; animation: dpmpulse 1s ease-in-out infinite; }
@keyframes dpmpulse { 50% { opacity: .25; } }
.dpm-sic .acts { display: flex; align-items: center; gap: 2px; flex: none; }
.dpm-sic .ib { position: relative; width: 30px; height: 30px; display: grid; place-items: center; flex: none; padding: 0; border: 0; border-radius: 8px; background: transparent; color: var(--dsw-alias-label-secondary); transition: background 140ms var(--ease), color 140ms var(--ease), transform 120ms var(--ease); }
.dpm-sic .ib:hover { background: var(--pm-on-chip); color: var(--dsw-alias-label-primary); }
.dpm-sic .ib:active { transform: scale(.9); }
.dpm-sic .ib.board svg { width: 15px; height: 15px; fill: currentColor; stroke: none; }
.dpm-sic .ib.board:hover { color: var(--pm-brand); }
.dpm-sic .sic-h .chev, .dpm-sic [data-tgl] .chev { transition: transform 260ms var(--ease); }
.dpm-sic svg.i.chev, .dpm-sic .ib svg.i { transition: transform 260ms var(--ease); }
/* 0.20: в свёрнутом виде стрелка вверх (клик разворачивает вверх), в развёрнутом — вниз */
.dpm-sic .acts [data-tgl] svg.i { transform: rotate(180deg); }
.dpm-sic.open .acts [data-tgl] svg.i { transform: none; }
.dpm-sic .mk { display: flex; align-items: center; gap: 6px; flex: 1; min-width: 0; height: 30px; padding: 0 4px 0 10px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 9px; background: var(--dsw-alias-bg-layer-1); transition: border-color 160ms var(--ease), box-shadow 160ms var(--ease); }
.dpm-sic .mk:focus-within { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); }
.dpm-sic .mk input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; font-size: 13px; }
.dpm-sic .mk .tok { display: flex; gap: 4px; flex: none; max-width: 45%; overflow: hidden; }
.dpm-sic .mk .tok span { height: 20px; padding: 0 6px; border-radius: 6px; background: var(--dsw-alias-bg-module-platform); border: 1px solid var(--dsw-alias-border-l2); font-size: 11px; line-height: 18px; white-space: nowrap; color: var(--dsw-alias-label-secondary); }
.dpm-sic .mk .tok span.file { border-color: var(--pm-brand-line); color: var(--pm-brand); }
.dpm-sic .btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 30px; padding: 0 10px; border: 1px solid var(--dsw-alias-border-l3); border-radius: 9px; background: var(--dsw-alias-bg-layer-1); font-size: 13px; font-weight: 500; white-space: nowrap; transition: background 140ms var(--ease), transform 120ms var(--ease); }
.dpm-sic .btn:hover { background: var(--dsw-alias-button-floating-hover, var(--pm-select)); }
.dpm-sic .btn:active { transform: scale(.97); }
.dpm-sic .btn.pri { background: var(--pm-brand); border-color: var(--pm-brand); color: var(--pm-brand-ink); }
.dpm-sic .btn.pri:hover { filter: brightness(1.06); background: var(--pm-brand); }
.dpm-sic .btn.sm { min-height: 26px; padding: 0 8px; font-size: 12px; border-radius: 8px; }
.dpm-sic .btn:disabled { opacity: .5; cursor: default; transform: none; }
.dpm-sic .btn svg.i { width: 14px; height: 14px; }
.dpm-sic .btn.danger { border-color: color-mix(in srgb, var(--pm-bad) 45%, transparent); color: var(--pm-bad); }
.dpm-sic .btn.danger:hover { background: color-mix(in srgb, var(--pm-bad) 8%, transparent); }
.dpm-sic .btn.danger.solid { background: var(--pm-bad); border-color: var(--pm-bad); color: #fff; }
.dpm-sic .btn.danger.ghost { min-height: 22px; padding: 0 6px; border-color: transparent; background: transparent; }
.dpm-sic .btn.danger.ghost:hover { border-color: color-mix(in srgb, var(--pm-bad) 45%, transparent); }
.dpm-sic .spin { width: 13px; height: 13px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: dpmrot .7s linear infinite; }
@keyframes dpmrot { to { transform: rotate(360deg); } }
.dpm-sic .sic-b { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 320ms var(--ease); }
.dpm-sic.open .sic-b { grid-template-rows: 1fr; }
.dpm-sic .sic-b > .in { min-height: 0; overflow: hidden; }
.dpm-sic .scroll { max-height: min(52vh, 460px); overflow: auto; padding: 2px 10px 10px; border-top: 1px solid var(--dsw-alias-border-l2); }
.dpm-sic.on .scroll { border-top-color: color-mix(in srgb, var(--pm-brand-line) 70%, transparent); }
.dpm-sic .grp { margin-top: 10px; border-radius: 12px; background: var(--pm-on-grp); padding: 8px; opacity: 0; transform: translateY(6px); transition: opacity 260ms var(--ease), transform 260ms var(--ease); }
.dpm-sic.open .grp { opacity: 1; transform: none; }
.dpm-sic.open .grp + .grp { transition-delay: 70ms; }
.dpm-sic .grp-h { display: flex; align-items: center; gap: 8px; height: 30px; padding: 0 4px 0 6px; font-size: 12px; font-weight: 650; color: var(--dsw-alias-label-secondary); }
.dpm-sic .grp-h svg.i { width: 14px; height: 14px; }
.dpm-sic .grp-h .n { height: 18px; padding: 0 6px; border-radius: 999px; background: var(--dsw-alias-bg-layer-1); font-size: 11px; line-height: 18px; font-variant-numeric: tabular-nums; }
.dpm-sic .sp { flex: 1; }
.dpm-sic .lnk { border: 0; background: transparent; color: var(--pm-brand); font-size: 12px; font-weight: 500; padding: 2px 4px; border-radius: 6px; }
.dpm-sic .lnk:hover { background: var(--pm-brand-soft); }
.dpm-sic .lfs { display: flex; flex-direction: column; gap: 6px; }
.dpm-sic .lf { display: flex; align-items: center; gap: 10px; min-height: 52px; padding: 8px 8px 8px 10px; border-radius: 10px; background: var(--dsw-alias-bg-layer-1); border: 1px solid var(--dsw-alias-border-l2); transition: border-color 200ms var(--ease); }
.dpm-sic .lf .txt { flex: 1; min-width: 0; }
.dpm-sic .lf .l1 { display: flex; align-items: center; gap: 6px; min-width: 0; }
.dpm-sic .lf .nm { font-weight: 650; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic .lf .pj { flex: none; font-size: 12px; color: var(--dsw-alias-label-secondary); }
.dpm-sic .tag { flex: none; height: 18px; padding: 0 6px; border-radius: 5px; border: 1px solid var(--dsw-alias-border-l2); font-size: 11px; line-height: 16px; color: var(--dsw-alias-label-secondary); white-space: nowrap; }
.dpm-sic .lf .l2 { margin-top: 2px; font-size: 12px; color: var(--dsw-alias-label-secondary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dpm-sic .lf .st { display: inline-flex; align-items: center; gap: 4px; flex: none; font-size: 12px; color: var(--dsw-alias-label-secondary); white-space: nowrap; font-variant-numeric: tabular-nums; }
.dpm-sic .lf .st svg.i { width: 13px; height: 13px; color: var(--pm-ok); }
.dpm-sic .lf .st .pend { color: var(--pm-brand); }
.dpm-sic .lf.busy { border-color: var(--pm-brand-line); background: linear-gradient(90deg, var(--dsw-alias-bg-layer-1) 0%, var(--pm-brand-soft) 50%, var(--dsw-alias-bg-layer-1) 100%); background-size: 200% 100%; animation: dpmshimmer 1.4s linear infinite; }
@keyframes dpmshimmer { to { background-position: -200% 0; } }
.dpm-sic .lf.picked { border-color: var(--pm-brand); box-shadow: 0 0 0 1px var(--pm-brand); }
.dpm-sic .lf.fresh, .dpm-sic .unit.fresh { animation: dpmfresh 1.1s var(--ease); }
@keyframes dpmfresh { 0%, 40% { border-color: var(--pm-brand); box-shadow: 0 0 0 3px var(--pm-brand-soft); } }
.dpm-sic .unit { border: 1px solid var(--pm-brand-line); border-radius: 10px; background: var(--dsw-alias-bg-layer-1); overflow: hidden; }
.dpm-sic .unit > .lf { border: 0; border-radius: 0; }
.dpm-sic .dn { border-top: 1px dashed var(--pm-brand-line); }
.dpm-sic .dn-h { display: flex; align-items: center; gap: 8px; width: 100%; height: 34px; padding: 0 6px 0 10px; border: 0; background: color-mix(in srgb, var(--pm-brand-soft) 60%, transparent); font-size: 12.5px; text-align: left; transition: background 140ms var(--ease); }
.dpm-sic .dn-h:hover { background: var(--pm-brand-soft); }
